prompt loading menu items for category: Breakfast
prompt script generated: 2025-08-17 21:10:29

set feedback on;
set serveroutput on;

declare

    l_count number;
    c menu_categories.category_name%type;

    type t_category_ids is table of integer index by varchar2(100);
    l_categories t_category_ids;

    procedure load_categories_array
    is
    begin
        l_categories := t_category_ids(for r in (select category_name, category_id from menu_categories) index r.category_name => r.category_id);
    end load_categories_array;

     procedure create_item(
        p_category_name in varchar2, 
        p_item_name in varchar2, 
        p_description in varchar2, 
        p_created_by in varchar2 default 'sample')
     is
        l_category_id integer := l_categories(p_category_name);
     begin     
        savepoint new_menu_item;

        insert into menu_items (item_name, category_id, item_description, created_by)
        values (p_item_name, l_category_id, p_description, p_created_by);
    exception
        when others then
            rollback to new_menu_item;
            dbms_output.put_line('Error inserting item: ' || p_item_name || ' SQLERRM: ' || sqlerrm);            
     end create_item;

begin

    load_categories_array;
 

    c := 'Breakfast';
    delete menu_items 
    where category_id = l_categories(c);

    dbms_output.put_line('Deleted ' || sql%rowcount || ' existing menu items for category: ' || c);

 


create_item(c, q'~Australian Vegemite Toast~', q'~Buttered sourdough toast spread with savory Vegemite and topped with creamy sliced avocado. A beloved Australian breakfast staple, often enjoyed with a sprinkle of grated cheddar cheese and a side of fresh fruit.~');
create_item(c, q'~Avocado Toast~', q'~Toasted artisan sourdough bread topped with creamy, freshly smashed ripe avocado, finished with a sprinkle of flaky sea salt and cracked black pepper. Garnished with thinly sliced radishes, microgreens, and a drizzle of extra virgin olive oil. Optional toppings include a perfectly poached egg, juicy heirloom tomato slices, or crumbled feta cheese for added richness and flavor. Served open-faced and accompanied by a wedge of lemon for a bright, refreshing breakfast experience.~');
create_item(c, q'~Bagel with Cream Cheese~', q'~A freshly toasted bagel, crisp on the outside and chewy inside, generously spread with smooth, tangy cream cheese. Often served plain or with toppings like smoked salmon, capers, or sliced tomatoes for a classic breakfast treat. Accompanied by a side of fresh fruit or a light salad for a balanced meal.~');
create_item(c, q'~Belgian Liege Waffle~', q'~Rich, chewy waffle made with pearl sugar, caramelized on the outside and soft within. Served warm with whipped cream, fresh berries, and a drizzle of chocolate sauce for a decadent Belgian breakfast treat.~');
create_item(c, q'~Brazilian Pão de Queijo~', q'~Warm, chewy cheese bread balls made from tapioca flour and aged Parmesan cheese. Naturally gluten-free and perfect for breakfast or snacking, these Brazilian treats are served fresh from the oven and often enjoyed with a cup of strong coffee.~');
create_item(c, q'~Breakfast Burrito~', q'~A large flour tortilla filled with fluffy scrambled eggs, melted cheddar cheese, savory sausage or crispy bacon, golden hash brown potatoes, and zesty salsa. Rolled up and grilled for a warm, hearty breakfast. Served with a side of guacamole and pico de gallo for extra flavor.~');
create_item(c, q'~Breakfast Sandwich~', q'~A hearty morning sandwich featuring a freshly cooked egg, gooey melted cheese, and crispy bacon layered on a toasted English muffin or buttery croissant. Served hot and perfect for a grab-and-go breakfast, with optional additions like sliced tomato, avocado, or spinach for extra nutrition.~');
create_item(c, q'~Chinese Jianbing~', q'~Savory Chinese crepe made with mung bean and wheat flour, layered with a fresh egg, scallions, cilantro, crispy wonton crackers, and sweet hoisin sauce. Rolled and served hot, often enjoyed as a street food breakfast in China. Customizable with chili paste or pickled vegetables for extra flavor.~');
create_item(c, q'~Colombian Arepa de Huevo~', q'~Cornmeal cake stuffed with a whole egg and deep-fried until crispy and golden. Served with tangy ají sauce and a side of fresh fruit for a Colombian breakfast specialty.~');
create_item(c, q'~Costa Rican Gallo Pinto~', q'~Savory mix of rice and black beans sautéed with onions, bell peppers, and fresh cilantro. Served with fried eggs, crispy plantains, and a side of sour cream for a traditional Costa Rican breakfast plate.~');
create_item(c, q'~Cuban Tostada con Café~', q'~Buttered Cuban bread pressed and toasted until crisp, served with a shot of sweet café con leche. Often enjoyed with a side of fresh tropical fruit for a classic Cuban breakfast.~');
create_item(c, q'~Danish Smørrebrød with Egg~', q'~Open-faced rye bread sandwich topped with sliced boiled eggs, pickled herring, fresh dill, and tangy mustard sauce. Served with a side of crisp cucumber salad for a traditional Danish breakfast.~');
create_item(c, q'~Eggs Benedict~', q'~Poached eggs and Canadian bacon layered on toasted English muffin halves, topped with rich, velvety hollandaise sauce. Served with breakfast potatoes and a garnish of fresh chives or parsley. A classic brunch dish known for its creamy, savory flavors and elegant presentation.~');
create_item(c, q'~Egyptian Ful Medames~', q'~Slow-cooked fava beans seasoned with garlic, lemon juice, olive oil, and earthy cumin. Garnished with chopped parsley, diced tomatoes, and sliced hard-boiled eggs, and served with warm pita bread for a nutritious, protein-rich breakfast.~');
create_item(c, q'~Ethiopian Firfir~', q'~Shredded injera, a spongy Ethiopian flatbread, tossed with spicy berbere sauce, sautéed onions, and ripe tomatoes. Served warm and garnished with fresh herbs, offering a hearty, flavorful breakfast with a unique tangy and spicy profile.~');
create_item(c, q'~Filipino Tapsilog~', q'~Garlic fried rice, tender marinated beef tapa, and a sunny-side-up egg, served with pickled papaya (atchara) and sliced tomatoes. A hearty Filipino breakfast plate that balances savory, sweet, and tangy flavors for a satisfying start to the day.~');
create_item(c, q'~Finnish Karjalanpiirakka~', q'~Traditional rye pastry filled with creamy rice porridge, topped with a generous dollop of egg butter. Served warm and often accompanied by slices of cheese and fresh cucumber for a Finnish breakfast treat.~');
create_item(c, q'~French Croque Madame~', q'~Grilled ham and Gruyère cheese sandwich topped with creamy béchamel sauce and a perfectly fried egg. Served hot for a decadent French breakfast, often accompanied by a light salad or crispy potatoes.~');
create_item(c, q'~French Toast~', q'~Slices of thick-cut bread soaked in a cinnamon-vanilla egg mixture, pan-fried until golden brown and slightly crisp. Served with a dusting of powdered sugar, a drizzle of warm maple syrup, and a medley of fresh berries. Optional toppings include whipped cream, toasted nuts, or caramelized bananas for a decadent breakfast.~');
create_item(c, q'~German Bauernfrühstück~', q'~Hearty farmer’s breakfast of sautéed potatoes, sweet onions, crispy bacon, and scrambled eggs, finished with fresh parsley and chives. Served hot and often accompanied by slices of rustic bread and pickled vegetables.~');
create_item(c, q'~Gluten-Free Almond Flour Pancakes~', q'~Fluffy pancakes made with almond flour, served warm with fresh berries and pure maple syrup. Perfect for gluten-sensitive guests, these pancakes are light, nutty, and satisfying.~');
