create_item(c, q'~Gluten-Free Sweet Potato Hash~', q'~Roasted sweet potatoes tossed with tender kale, caramelized red onions, and hearty black beans, topped with a perfectly poached egg. Served with a side of fresh salsa for a gluten-free breakfast option.~');
create_item(c, q'~Greek Spanakopita Omelette~', q'~Fluffy omelette filled with sautéed spinach, tangy feta cheese, fresh dill, and scallions. Inspired by the classic Greek pastry, this breakfast dish is served hot and garnished with lemon wedges and olives for a Mediterranean touch.~');
create_item(c, q'~Hawaiian Loco Moco~', q'~Steamed rice topped with a juicy hamburger patty, a perfectly fried egg, and rich brown gravy. Served with a side of macaroni salad and fresh pineapple for a comforting Hawaiian breakfast bowl.~');
