create_item(c, q'~Indian Masala Dosa~', q'~A crispy, golden fermented rice and lentil crepe filled with spicy potato masala, seasoned with mustard seeds, curry leaves, and turmeric. Served with cooling coconut chutney and tangy sambar for dipping. A South Indian breakfast classic, both gluten-free and vegetarian.~');
create_item(c, q'~Indonesian Bubur Ayam~', q'~Chicken rice porridge garnished with crispy fried shallots, sliced scallions, roasted peanuts, and crunchy crackers. Served with sweet soy sauce and spicy chili paste for a comforting Indonesian breakfast bowl.~');
create_item(c, q'~Iranian Kuku Sabzi~', q'~Herb-packed Persian frittata made with parsley, cilantro, dill, scallions, and crunchy walnuts. Baked until set and sliced into wedges, served with flatbread and yogurt for a nutritious Iranian breakfast.~');
create_item(c, q'~Irish Boxty~', q'~Crispy potato pancake made with a blend of grated and mashed potatoes, pan-fried until golden brown. Served with smoked salmon, chive sour cream, and a side of sautéed greens for a classic Irish breakfast experience.~');
create_item(c, q'~Israeli Shakshuka with Feta~', q'~Eggs poached in a spicy tomato and bell pepper sauce, topped with crumbled feta cheese and fresh parsley. Served with warm pita bread for dipping into the rich, flavorful sauce. A Mediterranean breakfast favorite, both vegetarian and protein-rich.~');
