create_item(c, q'~Jamaican Ackee and Saltfish~', q'~Ackee fruit sautéed with salted cod, onions, tomatoes, and fiery Scotch bonnet peppers. Served with crispy fried dumplings, sweet plantains, and a side of callaloo for a vibrant, flavorful Jamaican breakfast plate.~');
create_item(c, q'~Japanese Tamago Sando~', q'~Fluffy Japanese egg salad made with creamy Kewpie mayonnaise, finely chopped eggs, and a touch of white pepper, sandwiched between pillowy slices of milk bread. Served chilled and cut into neat rectangles for a delicate, satisfying breakfast or snack. Often enjoyed with a side of pickled vegetables.~');
