create_item(c, q'~Vegan Strawberry Almond Breakfast Bars~', q'~Soft-baked bars made with hearty oats, creamy almond butter, sweet strawberries, and ground flaxseed. Each bar is dairy-free and gluten-free, baked until golden, and finished with a drizzle of almond glaze. Perfect for a quick vegan breakfast or snack, these bars are both wholesome and delicious.~');
create_item(c, q'~Vegan Sweet Potato Breakfast Burrito~', q'~A hearty whole wheat tortilla stuffed with oven-roasted sweet potatoes, hearty black beans, creamy avocado slices, and spicy homemade salsa. The filling is seasoned with cumin and smoked paprika, then wrapped and grilled for a warm, satisfying bite. Served with a side of fresh fruit salad and a wedge of lime, this vegan breakfast burrito offers a balance of sweet, savory, and spicy flavors, perfect for a nourishing start to the day.~');
create_item(c, q'~Vegan Tofu Breakfast Tacos~', q'~Soft corn tortillas filled with seasoned scrambled tofu, sautéed bell peppers, sweet onions, and zesty avocado salsa. Each taco is topped with fresh cilantro, sliced radishes, and a squeeze of lime. Served with a side of smoky black beans and a tangy tomato salsa, these dairy-free and gluten-free tacos offer a vibrant, protein-packed vegan breakfast bursting with flavor and color.~');
create_item(c, q'~Vegetarian Asparagus ~' || chr(38) || q'~ Goat Cheese Tart~', q'~Flaky puff pastry topped with roasted asparagus spears, creamy goat cheese, and fresh thyme. Baked until golden and served warm with a side of arugula salad dressed in lemon vinaigrette. The combination of crisp pastry and savory filling makes this tart a sophisticated vegetarian breakfast option.~');
create_item(c, q'~Vegetarian Broccoli ~' || chr(38) || q'~ Cheddar Breakfast Muffin~', q'~Savory muffins packed with steamed broccoli florets, sharp aged cheddar cheese, and sliced scallions. Each muffin is baked to a golden finish and served warm for a grab-and-go breakfast or snack. The tender crumb and cheesy flavor make these muffins a wholesome and convenient morning option.~');
create_item(c, q'~Vegetarian Broccoli ~' || chr(38) || q'~ Cheddar Breakfast Pizza~', q'~Crispy flatbread topped with scrambled eggs, steamed broccoli, sharp cheddar cheese, and sliced scallions. Baked until golden and served warm for a unique vegetarian breakfast.~');
create_item(c, q'~Vegetarian Broccoli ~' || chr(38) || q'~ Cheddar Quiche~', q'~A flaky pastry crust filled with fluffy eggs, steamed broccoli florets, and sharp aged cheddar cheese. Baked until set and golden, then sliced and served warm with a side of mixed greens and cherry tomatoes. This classic vegetarian breakfast is both comforting and delicious.~');
create_item(c, q'~Vegetarian Caprese Breakfast Sandwich~', q'~A toasted ciabatta roll layered with creamy fresh mozzarella, thick slices of ripe tomatoes, aromatic basil pesto, and a perfectly fried farm egg. Garnished with baby arugula and a drizzle of extra virgin olive oil, this Italian-inspired breakfast sandwich is served warm and accompanied by a side of crisp mixed greens. The combination of flavors and textures creates a memorable, savory breakfast experience.~');
create_item(c, q'~Vegetarian Cheddar ~' || chr(38) || q'~ Chive Biscuits~', q'~Flaky buttermilk biscuits loaded with sharp aged cheddar cheese and freshly chopped chives. Each biscuit is baked until golden brown, then served warm with whipped butter and a side of homemade fruit preserves. The savory richness of the cheese and aromatic chives is complemented by the tender crumb, making these biscuits a standout breakfast treat for any occasion.~');
create_item(c, q'~Vegetarian Greek Yogurt Parfait~', q'~Creamy Greek yogurt layered in a tall glass with golden honey, crunchy homemade granola, fresh seasonal berries, and toasted almonds. Each layer is carefully assembled for a beautiful presentation, and the parfait is finished with a sprig of mint and a dusting of cinnamon. Served chilled, this protein-packed breakfast is both refreshing and energizing, perfect for a light morning meal or snack.~');
create_item(c, q'~Vegetarian Mediterranean Breakfast Bowl~', q'~A protein-rich bowl featuring fluffy quinoa topped with roasted chickpeas, crisp cucumber slices, juicy cherry tomatoes, Kalamata olives, and creamy feta cheese. Finished with a tangy lemon-tahini dressing and garnished with fresh parsley and mint. Served with warm pita wedges and a side of marinated artichoke hearts, this Mediterranean-inspired breakfast is both refreshing and filling, ideal for a vibrant morning meal.~');
create_item(c, q'~Vegetarian Mushroom ~' || chr(38) || q'~ Gruyère Crepes~', q'~Thin, tender crepes filled with sautéed mushrooms, nutty Gruyère cheese, and fresh thyme. Each crepe is folded and served with a crisp side salad of mixed greens and cherry tomatoes. The savory filling and delicate crepe make this vegetarian breakfast both elegant and satisfying.~');
create_item(c, q'~Vegetarian Mushroom ~' || chr(38) || q'~ Spinach Strata~', q'~Savory breakfast casserole layered with sourdough bread, sautéed mushrooms, spinach, eggs, and Gruyère cheese. Baked until golden and served warm, perfect for brunch gatherings.~');
create_item(c, q'~Vegetarian Ricotta ~' || chr(38) || q'~ Spinach Stuffed Croissant~', q'~Buttery croissant filled with creamy ricotta cheese, sautéed spinach, and fresh herbs. Baked until golden and flaky, then served warm with a side of mixed greens and cherry tomatoes. The rich filling and crisp pastry make this vegetarian breakfast a decadent morning indulgence.~');
create_item(c, q'~Vegetarian Roasted Red Pepper ~' || chr(38) || q'~ Feta Omelette~', q'~A fluffy omelette filled with roasted red peppers, crumbled feta cheese, and fresh parsley. Cooked to perfection and served hot with a side of mixed greens tossed in lemon vinaigrette. The savory flavors and creamy texture make this vegetarian breakfast a flavorful way to start the day.~');
create_item(c, q'~Vegetarian Roasted Red Pepper ~' || chr(38) || q'~ Spinach Breakfast Muffin~', q'~Savory muffin packed with roasted red peppers, sautéed spinach, and feta cheese.~');
create_item(c, q'~Vegetarian Roasted Red Pepper ~' || chr(38) || q'~ Spinach Breakfast Pizza~', q'~Crispy flatbread topped with scrambled eggs, roasted red peppers, sautéed spinach, and tangy feta cheese. Baked until golden and served warm for a unique vegetarian breakfast.~');
create_item(c, q'~Vegetarian Roasted Sweet Potato Hash~', q'~Oven-roasted sweet potatoes, colorful bell peppers, caramelized onions, and tender spinach, all tossed together and topped with a perfectly fried farm egg. Served with a side of spicy salsa and fresh avocado slices, this hearty vegetarian breakfast is both filling and flavorful.~');
create_item(c, q'~Vegetarian Roasted Tomato ~' || chr(38) || q'~ Basil Breakfast Muffin~', q'~Savory muffin packed with roasted tomatoes, fresh basil leaves, and creamy mozzarella cheese. Served warm for a grab-and-go vegetarian breakfast.~');
create_item(c, q'~Vegetarian Roasted Tomato ~' || chr(38) || q'~ Mozzarella Strata~', q'~Savory breakfast casserole layered with oven-roasted tomatoes, creamy mozzarella cheese, fluffy eggs, and fresh basil. Baked until golden and served warm with a side of arugula salad and balsamic reduction. This comforting vegetarian breakfast is perfect for brunch gatherings.~');
create_item(c, q'~Vegetarian Roasted Vegetable Breakfast Muffin~', q'~Savory muffin packed with roasted zucchini, sweet bell peppers, caramelized onions, and sharp cheddar cheese. Served warm for a grab-and-go vegetarian breakfast.~');
create_item(c, q'~Vegetarian Roasted Vegetable Frittata~', q'~A fluffy egg frittata packed with oven-roasted zucchini, sweet bell peppers, caramelized onions, and tangy feta cheese. Baked until golden and sliced into generous wedges, each serving is garnished with fresh basil and served warm with a side of mixed greens tossed in a light vinaigrette. This savory breakfast is perfect for brunch gatherings or a leisurely morning meal.~');
create_item(c, q'~Vegetarian Spinach ~' || chr(38) || q'~ Feta Breakfast Muffin~', q'~Savory muffin packed with sautéed spinach, crumbled feta cheese, and sliced scallions. Served warm for a grab-and-go vegetarian breakfast.~');
create_item(c, q'~Vegetarian Spinach ~' || chr(38) || q'~ Feta Breakfast Pizza~', q'~Crispy flatbread topped with scrambled eggs, sautéed spinach, crumbled feta, and cherry tomatoes. Baked until golden and served warm for a unique vegetarian breakfast.~');
create_item(c, q'~Vegetarian Spinach ~' || chr(38) || q'~ Feta Breakfast Wrap~', q'~Whole wheat wrap filled with fluffy scrambled eggs, sautéed spinach, and crumbled feta cheese. Served warm with a side of roasted potatoes and a fresh tomato salsa. This portable vegetarian breakfast option is both nutritious and flavorful, ideal for busy mornings.~');
create_item(c, q'~Vegetarian Spinach ~' || chr(38) || q'~ Mushroom Breakfast Muffin~', q'~Savory muffin packed with sautéed spinach, earthy mushrooms, and sharp cheddar cheese. Served warm for a grab-and-go vegetarian breakfast.~');
create_item(c, q'~Vegetarian Spinach ~' || chr(38) || q'~ Tomato Quiche~', q'~A flaky pastry crust filled with fluffy farm eggs, sautéed baby spinach, juicy cherry tomatoes, and nutty Swiss cheese. Baked until set and golden, then sliced and served warm with a side of herbed potatoes and fresh fruit. The combination of creamy filling and crisp crust makes this classic vegetarian quiche a breakfast favorite.~');
create_item(c, q'~Vegetarian Sweet Corn ~' || chr(38) || q'~ Zucchini Pancakes~', q'~Golden pancakes made with sweet corn kernels, shredded zucchini, and sliced scallions. Each pancake is pan-fried until crisp on the edges and tender inside, then served with tangy sour cream and spicy homemade salsa. Garnished with fresh cilantro and a wedge of lime, these savory vegetarian pancakes are a flavorful breakfast treat.~');
create_item(c, q'~Vegetarian Tomato ~' || chr(38) || q'~ Basil Breakfast Muffin~', q'~Savory muffin packed with roasted tomatoes, fresh basil leaves, and creamy mozzarella cheese. Served warm for a grab-and-go vegetarian breakfast.~');
create_item(c, q'~Vegetarian Tomato ~' || chr(38) || q'~ Basil Breakfast Pizza~', q'~Crispy flatbread topped with fluffy scrambled eggs, juicy cherry tomatoes, creamy mozzarella cheese, and fresh basil leaves. Baked until golden and served warm with a drizzle of olive oil and a sprinkle of sea salt. This unique vegetarian breakfast pizza is both flavorful and visually appealing.~');
create_item(c, q'~Vegetarian Zucchini ~' || chr(38) || q'~ Parmesan Frittata~', q'~A fluffy egg frittata packed with shredded zucchini, nutty Parmesan cheese, and fresh basil. Baked until golden and sliced into wedges, each serving is garnished with a dollop of sour cream and a sprinkle of chives. This light vegetarian breakfast is both nutritious and flavorful.~');
create_item(c, q'~Venezuelan Perico~', q'~Scrambled eggs cooked with ripe tomatoes, sweet onions, and colorful bell peppers, served with warm arepas and fresh cheese. A vibrant Venezuelan breakfast, often enjoyed with avocado slices and hot sauce.~');
create_item(c, q'~Vietnamese Bánh Mì Op La~', q'~Crispy French baguette filled with sunny-side-up eggs, pickled daikon and carrots, fresh cucumber slices, cilantro, and a drizzle of savory soy sauce. A fusion of French and Vietnamese flavors, often served with a side of spicy chili sauce for an extra kick.~');


    select count(*) into l_count 
    from menu_items
    where category_id = l_categories(c);

    dbms_output.put_line('Created ' || l_count || ' menu items for category: ' || c);    

    commit;


exception
    when others then
        dbms_output.put_line(sqlerrm);
end;
/


    

